window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-7069ae1631654e95"]={"versions": [{"id": "FIG-7069ae1631654e95", "releases": ["R4.0.3", "R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Prozessdiagramm zur Veranschaulichung der Metamodellierungs-Muster, Metamodell-Transformationen und des Varianten-Handlings über die OMG-Modellierungsebenen M2 (Metamodell-Ebene) und M1 (Modell-Ebene). Das Diagramm stellt dar, wie ausgehend von einem reinen AUTOSAR-Metamodell über Transformationsstufen Artefakte wie das XML-Schema abgeleitet werden und wie sich M1-Modelle (variantenreich vs. gebunden) zu den jeweiligen Metamodellstufen verhalten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schaubild umfasst folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Ebene (links):</strong></li>\n<li><code>Pure Metamodel</code>: Rechteckiger Block für das unannotierte Basis-Metamodell.</li>\n<li><code>Annotated Metamodel</code>: Rechteckiger Block für das um Variationspunkte angereicherte Metamodell.</li>\n<li><code>Extended Metamodel</code>: Rechteckiger Block für das nach Musterauflösung erweiterte Metamodell.</li>\n<li><code>XML Schema</code>: Ovale Entität im unteren Zentrum, repräsentiert das aus dem erweiterten Metamodell generierte Schema.</li>\n<li><strong>Modell-Ebene / M1 (rechts):</strong></li>\n<li><code>Variant rich M 1 Model</code>: Rechteckiger Block für das variantenbehaftete System-/Konfigurationsmodell.</li>\n<li><code>Bound M1 Model</code>: Rechteckiger Block für das nach erfolgter Variantenbindung resultierende Modell.</li>\n<li><strong>Beziehungen & gerichtete Transformationen:</strong></li>\n<li>Geradlinige vertikale Pfeile (abwärts, fett grau): Von <code>Pure Metamodel</code> zu <code>Annotated Metamodel</code> (beschriftet mit <code>+ Variation Points</code>) und von <code>Annotated Metamodel</code> zu <code>Extended Metamodel</code> (beschriftet mit <code>+ Pattern resolution</code>).</li>\n<li>Gekrümmter Pfeil (abwärts/rechts): Von <code>Extended Metamodel</code> zu <code>XML Schema</code> (beschriftet mit <code>creates</code>).</li>\n<li>Gekrümmter Pfeil (aufwärts/rechts): Von <code>XML Schema</code> zu <code>Variant rich M 1 Model</code> (beschriftet mit <code>defines</code>).</li>\n<li>Geradliniger vertikaler Pfeil (aufwärts, fett grau): Von <code>Variant rich M 1 Model</code> zu <code>Bound M1 Model</code> (beschriftet mit <code>Binding</code>).</li>\n<li>Horizontale gestrichelte Relationen (<code>Conforms To</code>): Zwischen <code>Pure Metamodel</code> und <code>Bound M1 Model</code> sowie zwischen <code>Extended Metamodel</code> und <code>Variant rich M 1 Model</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Transformations- und Verwendungszyklus gliedert sich in zwei Hauptpfade:</p>\n<ol class=\"fig-list\">\n<li><strong>Metamodell-Pipeline (M2):</strong> Das <code>Pure Metamodel</code> wird durch Anreicherung mit Variationspunkten (<code>+ Variation Points</code>) in das <code>Annotated Metamodel</code> überführt. Dieses wird durch Auflösung der Metamodellierungsmuster (<code>+ Pattern resolution</code>) zum <code>Extended Metamodel</code> transformiert. Aus dem <code>Extended Metamodel</code> wird das <code>XML Schema</code> erzeugt (<code>creates</code>).</li>\n<li><strong>Modell-Lebenszyklus (M1):</strong> Das <code>XML Schema</code> definiert (<code>defines</code>) die Struktur für das <code>Variant rich M 1 Model</code>. Dieses Modell ist konform (<code>Conforms To</code>) zum <code>Extended Metamodel</code>. Durch den Bindungsprozess (<code>Binding</code>) werden Variantenentscheidungen getroffen und ausgewertet, wodurch das <code>Bound M1 Model</code> entsteht. Das resultierende gebundene Modell ist konform (<code>Conforms To</code>) zur ursprünglichen, unvariierten Struktur des <code>Pure Metamodel</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für das Verständnis des AUTOSAR-Variantenmanagements und der Schemaerzeugung nach Generic Structure Template (GST). Werkzeugentwickler müssen beachten, dass Austauschformate (ARXML) auf Basis des <code>XML Schema</code> validiert werden, welches dem <code>Extended Metamodel</code> entspricht. Ein serialisiertes Modell vor Variantenauflösung enthält zusätzliche Variationsstrukturen. Erst nach Durchführung des <code>Binding</code> entspricht das bereinigte Modell semantisch der klaren Struktur des <code>Pure Metamodel</code>.</p>"}, {"id": "FIG-31c7507da3155b5e", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11", "R20-11", "R21-11", "R22-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Konzeptionelles Architektur- und Prozessdiagramm zur Veranschaulichung der Metamodellierungs-Muster, Metamodell-Transformationen und des Varianten-Handlings über die OMG-Modellierungsebenen M2 (Metamodell-Ebene) und M1 (Modell-Ebene). Das Diagramm stellt dar, wie ausgehend von einem reinen AUTOSAR-Metamodell über Transformationsstufen Artefakte wie das XML-Schema abgeleitet werden und wie sich M1-Modelle (variantenreich vs. gebunden) zu den jeweiligen Metamodellstufen verhalten.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Schaubild umfasst folgende Entitäten und Beziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>Metamodell-Ebene (links):</strong></li>\n<li><code>Pure Metamodel</code>: Rechteckiger Block für das unannotierte Basis-Metamodell.</li>\n<li><code>Annotated Metamodel</code>: Rechteckiger Block für das um Variationspunkte angereicherte Metamodell.</li>\n<li><code>Extended Metamodel</code>: Rechteckiger Block für das nach Musterauflösung erweiterte Metamodell.</li>\n<li><code>XML Schema</code>: Ovale Entität im unteren Zentrum, repräsentiert das aus dem erweiterten Metamodell generierte Schema.</li>\n<li><strong>Modell-Ebene / M1 (rechts):</strong></li>\n<li><code>Variant rich M 1 Model</code>: Rechteckiger Block für das variantenbehaftete System-/Konfigurationsmodell.</li>\n<li><code>Bound M1 Model</code>: Rechteckiger Block für das nach erfolgter Variantenbindung resultierende Modell.</li>\n<li><strong>Beziehungen & gerichtete Transformationen:</strong></li>\n<li>Geradlinige vertikale Pfeile (abwärts, fett grau): Von <code>Pure Metamodel</code> zu <code>Annotated Metamodel</code> (beschriftet mit <code>+ Variation Points</code>) und von <code>Annotated Metamodel</code> zu <code>Extended Metamodel</code> (beschriftet mit <code>+ Pattern resolution</code>).</li>\n<li>Gekrümmter Pfeil (abwärts/rechts): Von <code>Extended Metamodel</code> zu <code>XML Schema</code> (beschriftet mit <code>creates</code>).</li>\n<li>Gekrümmter Pfeil (aufwärts/rechts): Von <code>XML Schema</code> zu <code>Variant rich M 1 Model</code> (beschriftet mit <code>defines</code>).</li>\n<li>Geradliniger vertikaler Pfeil (aufwärts, fett grau): Von <code>Variant rich M 1 Model</code> zu <code>Bound M1 Model</code> (beschriftet mit <code>Binding</code>).</li>\n<li>Horizontale gestrichelte Relationen (<code>Conforms To</code>): Zwischen <code>Pure Metamodel</code> und <code>Bound M1 Model</code> sowie zwischen <code>Extended Metamodel</code> und <code>Variant rich M 1 Model</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Transformations- und Verwendungszyklus gliedert sich in zwei Hauptpfade:</p>\n<ol class=\"fig-list\">\n<li><strong>Metamodell-Pipeline (M2):</strong> Das <code>Pure Metamodel</code> wird durch Anreicherung mit Variationspunkten (<code>+ Variation Points</code>) in das <code>Annotated Metamodel</code> überführt. Dieses wird durch Auflösung der Metamodellierungsmuster (<code>+ Pattern resolution</code>) zum <code>Extended Metamodel</code> transformiert. Aus dem <code>Extended Metamodel</code> wird das <code>XML Schema</code> erzeugt (<code>creates</code>).</li>\n<li><strong>Modell-Lebenszyklus (M1):</strong> Das <code>XML Schema</code> definiert (<code>defines</code>) die Struktur für das <code>Variant rich M 1 Model</code>. Dieses Modell ist konform (<code>Conforms To</code>) zum <code>Extended Metamodel</code>. Durch den Bindungsprozess (<code>Binding</code>) werden Variantenentscheidungen getroffen und ausgewertet, wodurch das <code>Bound M1 Model</code> entsteht. Das resultierende gebundene Modell ist konform (<code>Conforms To</code>) zur ursprünglichen, unvariierten Struktur des <code>Pure Metamodel</code>.</li>\n</ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ für das Verständnis des AUTOSAR-Variantenmanagements und der Schemaerzeugung nach Generic Structure Template (GST). Werkzeugentwickler müssen beachten, dass Austauschformate (ARXML) auf Basis des <code>XML Schema</code> validiert werden, welches dem <code>Extended Metamodel</code> entspricht. Ein serialisiertes Modell vor Variantenauflösung enthält zusätzliche Variationsstrukturen. Erst nach Durchführung des <code>Binding</code> entspricht das bereinigte Modell semantisch der klaren Struktur des <code>Pure Metamodel</code>.</p>"}], "trans": [{"from": "FIG-7069ae1631654e95", "to": "FIG-31c7507da3155b5e", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
